// ===== PROCUREMENT AGENT: purchase price analysis =====
const S = $('Sozlamalar').first().json;
const FILIAL_NOMI = S.filial_nomi || 'MAIN BRANCH';
const TZ_OFFSET = 5 * 3600 * 1000;                     // Tashkent = UTC+5

// ---- helpers ----
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const grp = n => { const [a, b] = n.split('.'); return a.replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + (b ? '.' + b : ''); };
const num = (v, d = 0) => grp((Math.round(Number(v) * 10 ** d) / 10 ** d).toFixed(d));
const money = (v, cur) => cur === 'USD' ? '$' + num(v, 2) : num(v) + " so'm";
const tashDate = iso => new Date(new Date(iso).getTime() + TZ_OFFSET);
const dstr = iso => { const d = tashDate(iso); return String(d.getUTCDate()).padStart(2, '0') + '.' + String(d.getUTCMonth() + 1).padStart(2, '0'); };
const shiftDay = (k, n) => new Date(Date.parse(k + 'T00:00:00Z') + n * 864e5).toISOString().slice(0, 10);
const dayKey = iso => tashDate(iso).toISOString().slice(0, 10);

// ---- 1. USD rate (median of recent conversions) ----
let rate = null;
try {
  const k = $('Kurs').first().json;
  const rates = (k.data || []).filter(r => r.from_currency_code === 'UZS' && r.to_currency_code === 'USD' || r.from_currency_code === 'USD' && r.to_currency_code === 'UZS')
    .map(r => Number(r.exchange_rate)).filter(x => x > 1000).sort((a, b) => a - b);
  if (rates.length) rate = rates[Math.floor(rates.length / 2)];
} catch (e) { }
const toUZS = (v, cur) => cur === 'USD' ? (rate ? v * rate : null) : v;
const conv = (v, from, to) => { if (from === to) return v; if (!rate) return null; return from === 'USD' ? v * rate : v / rate; };

// ---- 2. collect all purchase lines ----
const lines = [];
const seenDoc = new Set();
const drafts = new Set();
const QABUL = 13;                                      // iBox: 11 = draft, 12 = pending, 13 = received
for (const page of $('Zakuplar').all()) {
  for (const doc of (page.json.data || [])) {
    if (seenDoc.has(doc.id)) continue;
    seenDoc.add(doc.id);
    if (Number(doc.status) !== QABUL) { drafts.add(doc.id); continue; }   // drafts / pending are skipped
    for (const l of (doc.purchase_details || [])) {
      const q = Number(l.quantity);
      if (!q) continue;
      lines.push({
        docId: doc.id, docNo: doc.number, date: doc.date, cur: doc.currency_code || 'UZS',
        supplier: doc.outlet_name, productId: l.product_id,
        name: l.product ? l.product.name : ('#' + l.product_id),
        unit: l.product && l.product.storage_unit ? l.product.storage_unit.short_name : '',
        qty: q, listPrice: Number(l.price), price: Number(l.total) / q,   // price after discount
        warehouse: l.warehouse ? l.warehouse.name : '',
      });
    }
  }
}

// ---- 3. which documents are "new" (to be checked) ----
const sd = $getWorkflowStaticData('global');
const todayKey = dayKey(new Date().toISOString());

// DATE MODE: if a date comes in (sinov_sana) (15.09.2026 or 2026-09-15),
// that day's purchases are compared with the history BEFORE it
let testKey = String(S.sinov_sana || '').trim();
let m = testKey.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
if (m) testKey = `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
const TEST = /^\d{4}-\d{2}-\d{2}$/.test(testKey);

let isNew, fresh, history;
if (TEST) {
  isNew = l => dayKey(l.date) === testKey;
  fresh = lines.filter(isNew);
  history = lines.filter(l => dayKey(l.date) < testKey);
} else {
  // every received document is checked exactly ONCE (even if approved later than it was drafted)
  if (sd.checked) isNew = l => !sd.checked[l.docId];
  else if (sd.lastDocId) isNew = l => l.docId > sd.lastDocId;   // migration from older version
  else isNew = l => dayKey(l.date) === todayKey;                // first run
  fresh = lines.filter(isNew);
  history = lines.filter(l => !isNew(l));
}

// history per product (sorted by date)
const byProduct = {};
for (const l of history) (byProduct[l.productId] ||= []).push(l);
for (const k in byProduct) byProduct[k].sort((a, b) => new Date(b.date) - new Date(a.date) || b.docId - a.docId);

// ---- 4. check every new line ----
const red = [], yellow = [], green = [], fresh1 = [];
for (const l of fresh) {
  const hist = byProduct[l.productId] || [];
  if (!hist.length) { fresh1.push(l); continue; }
  const prev = hist[0];
  const prevPrice = conv(prev.price, prev.cur, l.cur);
  if (prevPrice == null) { fresh1.push(l); continue; }
  // 90-day quantity-weighted average, in the current currency
  let sq = 0, sv = 0;
  for (const h of hist) { const p = conv(h.price, h.cur, l.cur); if (p != null) { sq += h.qty; sv += p * h.qty; } }
  const avg = sq ? sv / sq : null;
  const diff = l.price - prevPrice;
  const pct = prevPrice ? diff / prevPrice * 100 : 0;
  const eps = l.cur === 'USD' ? 0.005 : 0.5;
  const r = { ...l, prev, prevPrice, avg, diff, pct, sumDiff: diff * l.qty, sumDiffUZS: toUZS(diff * l.qty, l.cur) };
  if (diff > eps) red.push(r);
  else if (diff < -eps) yellow.push(r);
  else green.push(r);
}
red.sort((a, b) => (b.sumDiffUZS ?? 0) - (a.sumDiffUZS ?? 0));
yellow.sort((a, b) => (a.sumDiffUZS ?? 0) - (b.sumDiffUZS ?? 0));

// ---- 5. build the Telegram message ----
const docsFresh = new Set(fresh.map(l => l.docId)).size;
const overUZS = red.reduce((s, r) => s + (r.sumDiffUZS ?? 0), 0);
const saveUZS = yellow.reduce((s, r) => s - (r.sumDiffUZS ?? 0), 0);
const d = TEST ? new Date(testKey + 'T00:00:00Z') : tashDate(new Date().toISOString());
const today = String(d.getUTCDate()).padStart(2, '0') + '.' + String(d.getUTCMonth() + 1).padStart(2, '0') + '.' + d.getUTCFullYear();

const blocks = [];
let head = (TEST ? '📅 <i>Tanlangan sana bo\'yicha hisobot</i>\n' : '') + `📦 <b>TA'MINOT HISOBOTI — ${today}</b>\n🏢 ${esc(FILIAL_NOMI)}\n\n`;
if (!fresh.length) {
  head += TEST ? '✅ Bu sanada zakup topilmadi.' : '✅ Oxirgi hisobotdan beri yangi zakup kiritilmagan.';
  blocks.push(head);
} else {
  head += `Tekshirildi: <b>${docsFresh}</b> ta hujjat, <b>${fresh.length}</b> ta tovar qatori\n\n`;
  head += `🔴 Qimmat olingan: <b>${red.length}</b> ta — ortiqcha to'lov: <b>${num(overUZS)} so'm</b>\n`;
  head += `🟡 Arzon olingan (tekshiring): <b>${yellow.length}</b> ta — farq: ${num(saveUZS)} so'm\n`;
  head += `🟢 Narx o'zgarmagan: ${green.length} ta\n`;
  head += `🆕 Yangi tovar (90 kunda birinchi xarid): ${fresh1.length} ta\n`;
  if (drafts.size) head += `📝 Tasdiqlanmagan (chernovik) zakuplar: ${drafts.size} ta — tahlilga kiritilmadi\n`;
  if (rate) head += `\n<i>Dollar kursi: ${num(rate)} so'm</i>`;
  blocks.push(head);

  const item = (r, i, sign) => {
    let s = `${i + 1}. <b>${esc(r.name)}</b>\n`;
    s += `   🏭 ${esc(r.supplier)}\n`;
    s += `   ${money(r.price, r.cur)} ← avval ${money(r.prevPrice, r.cur)} (${dstr(r.prev.date)}) · <b>${r.pct > 0 ? '+' : ''}${num(r.pct, 1)}%</b>\n`;
    s += `   ${num(r.qty, 2).replace(/\.00$/, '')} ${esc(r.unit)} · ${sign}: <b>${r.sumDiffUZS != null ? num(Math.abs(r.sumDiffUZS)) + " so'm" : money(Math.abs(r.sumDiff), r.cur)}</b>`;
    if (r.avg != null) s += ` · 90 kun o'rtacha: ${money(r.avg, r.cur)}`;
    s += `\n   📄 №${esc(r.docNo)} (${dstr(r.date)}) · ${esc(r.warehouse)}`;
    if (Math.abs(r.listPrice - r.price) > (r.cur === 'USD' ? 0.005 : 0.5)) s += ` · <i>chegirma bilan (prays ${money(r.listPrice, r.cur)})</i>`;
    if (sign === 'farq' && r.pct <= -50) s += `\n   ⚠️ <b>Narx 2 barobardan ko'p tushgan — kiritishda xato bo'lishi mumkin!</b>`;
    if (sign === 'ortiqcha' && r.pct >= 100) s += `\n   ⚠️ <b>Narx 2 barobardan ko'p oshgan — kiritishda xato bo'lishi mumkin!</b>`;
    return s;
  };
  if (red.length) { blocks.push('🔴 <b>QIMMAT OLINGAN</b>'); red.forEach((r, i) => blocks.push(item(r, i, 'ortiqcha'))); }
  if (yellow.length) { blocks.push('🟡 <b>ARZON OLINGAN — rostdan arzonmi, tekshiring</b>'); yellow.forEach((r, i) => blocks.push(item(r, i, 'farq'))); }
  if (fresh1.length) {
    blocks.push('🆕 <b>YANGI TOVARLAR</b> (solishtirish uchun tarix yo\'q)\n' +
      fresh1.slice(0, 30).map(l => `• ${esc(l.name)} — ${money(l.price, l.cur)} · ${esc(l.supplier)}`).join('\n') +
      (fresh1.length > 30 ? `\n… va yana ${fresh1.length - 30} ta` : ''));
  }
}

// Telegram limit is 4096 chars — split into chunks
const msgs = []; let cur = '';
for (const b of blocks) {
  if ((cur + '\n\n' + b).length > 3800) { if (cur) msgs.push(cur); cur = b.slice(0, 3800); }
  else cur = cur ? cur + '\n\n' + b : b;
}
if (cur) msgs.push(cur);

// remember checked documents so the next run only looks at new ones
if (!TEST) {
  const chk = sd.checked || {};
  for (const l of lines) chk[l.docId] = dayKey(l.date);
  const cutoff = shiftDay(todayKey, -120);
  for (const id in chk) if (chk[id] < cutoff) delete chk[id];
  sd.checked = chk;
  delete sd.lastDocId;
}

return msgs.map((text, i) => ({ json: { text, qism: i + 1, jami: msgs.length } }));
